#!/usr/bin/env bash
# SessionStart hook: prints the offload table (offload-policy.md next to this script, generated by
# scripts/port.py from user-config/offload-policy.md) as plain standard output, which Claude Code adds to the context.
# Silent, and always exit 0, whatever happens: a failing hook would disturb every session.
# Silent when: the option offload_policy is exactly "false" (an untouched option leaves the variable unset, so
# the default is on); inside `claude plugin eval` (CLAUDE_CODE_EVAL_CONFINED set) unless EVAL_OFFLOAD_HOOK is
# exactly "on", so cases measure the plugin without the table unless they ask for it; or the user's own CLAUDE.md
# already holds the table (exact heading line), so it is not loaded twice.
[ "${CLAUDE_PLUGIN_OPTION_OFFLOAD_POLICY:-}" = "false" ] && exit 0
[ -n "${CLAUDE_CODE_EVAL_CONFINED+x}" ] && [ "${EVAL_OFFLOAD_HOOK:-}" != "on" ] && exit 0
config="${CLAUDE_CONFIG_DIR:-${HOME:+$HOME/.claude}}"
if [ -n "$config" ] && grep -qxF '## Offload policy (main conversation only)' "$config/CLAUDE.md" 2>/dev/null; then
  exit 0
fi
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" 2>/dev/null && pwd)" || exit 0
[ -r "$here/offload-policy.md" ] && cat "$here/offload-policy.md" 2>/dev/null
exit 0
